/* MSL embed shim — phục vụ ảnh/GLB nhúng sẵn thay cho thư mục assets/. Không sửa tay. */
(function(){
var E=window.MSL_EMBED=window.MSL_EMBED||{};E.files=E.files||{};E.fb=E.fb||{};
if(E.on)return;E.on=1;
var base=new URL('.',document.baseURI).href;
function key(u){if(!u)return'';u=String(u);if(/^(data|blob|javascript|mailto):/i.test(u))return'';
 var a;try{a=new URL(u,document.baseURI).href}catch(e){return''}
 if(a.indexOf(base)!==0)return'';return decodeURIComponent(a.slice(base.length).split('#')[0].split('?')[0])}
function emb(u){var k=key(u);return k?(E.files[k]||E.fb[k]||null):null}
var of=window.fetch&&window.fetch.bind(window);
if(of)window.fetch=function(input,init){
 var url=typeof input==='string'?input:((input&&input.url)||String(input)),k=key(url);
 if(k&&E.files[k])return of(E.files[k]);
 if(k&&E.fb[k])return of(input,init).then(function(r){return r.ok?r:of(E.fb[k])},function(){return of(E.fb[k])});
 return of(input,init)};
function fix(el){if(!el||el.nodeType!==1)return;
 var l=(el.matches&&el.matches('img,a[href],source'))?[el]:[];
 if(el.querySelectorAll)l=l.concat([].slice.call(el.querySelectorAll('img,a[href],source')));
 l.forEach(function(n){var at=n.tagName==='A'?'href':'src',v=n.getAttribute(at),d=emb(v);if(d&&v!==d)n.setAttribute(at,d)})}
new MutationObserver(function(ms){ms.forEach(function(m){if(m.type==='attributes')fix(m.target);else[].forEach.call(m.addedNodes,fix)})})
 .observe(document.documentElement,{childList:true,subtree:true,attributes:true,attributeFilter:['src','href']});
document.addEventListener('click',function(e){var a=e.target.closest&&e.target.closest('a[href^="data:"]');
 if(!a||a.hasAttribute('download'))return;e.preventDefault();var w=window.open('','_blank');
 fetch(a.href).then(function(r){return r.blob()}).then(function(b){var u=URL.createObjectURL(b);if(w)w.location.href=u;else location.href=u})},true);
})();

/* Prime Mecha: GLB + concept + preview (WebP) */
(function(){var E=window.MSL_EMBED;
Object.assign(E.files,{"assets/prime_mecha/van-kiem/van-kiem.glb": "data:model/gltf-binary;base64,", "assets/prime_mecha/van-kiem-concept.png": "data:image/webp;base64,", "assets/prime_mecha/van-kiem/van-kiem-preview-front.png": "data:image/webp;base64,", "assets/prime_mecha/van-kiem/van-kiem-preview-3quarter.png": "data:image/webp;base64,", "assets/prime_mecha/van-kiem/van-kiem-preview-back.png": "data:image/webp;base64,", "assets/prime_mecha/thien-van-phao-co/thien-van-phao-co.glb": "data:model/gltf-binary;base64,", "assets/prime_mecha/thien-van-phao-co-concept.png": "data:image/webp;base64,", "assets/prime_mecha/thien-van-phao-co/thien-van-phao-co-preview-front.png": "data:image/webp;base64,", "assets/prime_mecha/thien-van-phao-co/thien-van-phao-co-preview-3quarter.png": "data:image/webp;base64,", "assets/prime_mecha/thien-van-phao-co/thien-van-phao-co-preview-back.png": "data:image/webp;base64,", "assets/prime_mecha/comparison-3d-models.jpg": "data:image/webp;base64,"});
Object.assign(E.fb,{"database/prime-mecha.json": "data:application/json;base64,"});
})();
